import{_ as t,o as i,c as h,a2 as o}from"./chunks/framework.BBd5PKnH.js";const d=JSON.parse('{"title":"Celestial condition vs. Terrestrial disposition","description":"","frontmatter":{"title":"Celestial condition vs. Terrestrial disposition","date":"2026-09-06T00:00:00.000Z"},"headers":[],"relativePath":"astro/note_1.md","filePath":"astro/note_1.md"}'),a={name:"astro/note_1.md"};function s(r,n,c,e,g,u){return i(),h("div",null,[...n[0]||(n[0]=[o(`<h2 id="phan-1-celestial-condition-vs-terrestrial-disposition" tabindex="-1">Phần 1: Celestial condition vs. Terrestrial disposition <a class="header-anchor" href="#phan-1-celestial-condition-vs-terrestrial-disposition" aria-label="Permalink to &quot;Phần 1: Celestial condition vs. Terrestrial disposition&quot;">​</a></h2><p><strong>Dịch ý:</strong> Các nhà chiêm tinh cổ điển phân biệt giữa <strong>&quot;celestial condition&quot;</strong> (tình trạng thiên thể) và <strong>&quot;terrestrial disposition&quot;</strong> (sự sắp đặt trên mặt đất) của một hành tinh. Đây chính là cặp khái niệm mà các nhà chiêm tinh thời Trung Cổ gọi là <strong>essential dignity</strong> và <strong>accidental dignity</strong>.</p><p><strong>Thuật ngữ mới — Essential dignity vs Accidental dignity:</strong></p><table tabindex="0"><thead><tr><th></th><th>Essential dignity</th><th>Accidental dignity</th></tr></thead><tbody><tr><td><strong>Tương ứng với</strong></td><td>Celestial condition</td><td>Terrestrial disposition</td></tr><tr><td><strong>Nghĩa đen</strong></td><td>&quot;phẩm giá cốt yếu/nội tại&quot;</td><td>&quot;phẩm giá ngẫu nhiên/tùy hoàn cảnh&quot;</td></tr><tr><td><strong>Ý nghĩa</strong></td><td>Hành tinh mạnh/yếu do <strong>bản chất của chính nó</strong> — vị trí trong zodiac (sign, decan) và mối quan hệ với Mặt Trời (solar phase)</td><td>Hành tinh mạnh/yếu do <strong>hoàn cảnh bên ngoài</strong> — nó rơi vào house nào, có angular hay không</td></tr></tbody></table><p>→ <strong>Điểm mấu chốt:</strong> &quot;Essential&quot; (từ Latin <em>essentia</em> = bản chất) nghĩa là <strong>thuộc về bản thân hành tinh</strong> — không phụ thuộc vào từng cá nhân sinh ra ngày hôm đó. &quot;Accidental&quot; (từ Latin <em>accidens</em> = cái xảy đến/tình cờ) nghĩa là phụ thuộc vào <strong>hoàn cảnh cụ thể</strong> — cụ thể ở đây là house, thứ khác nhau tùy giờ sinh, nơi sinh của từng người.</p><h2 id="phan-2-vi-sao-celestial-condition-giong-nhau-cho-moi-nguoi-sinh-cung-ngay" tabindex="-1">Phần 2: Vì sao celestial condition giống nhau cho mọi người sinh cùng ngày? <a class="header-anchor" href="#phan-2-vi-sao-celestial-condition-giong-nhau-cho-moi-nguoi-sinh-cung-ngay" aria-label="Permalink to &quot;Phần 2: Vì sao celestial condition giống nhau cho mọi người sinh cùng ngày?&quot;">​</a></h2><p><strong>Dịch ý:</strong> Tình trạng thiên thể (celestial condition) mô tả hành tinh nằm ở đâu trên bầu trời vào một ngày cụ thể. Vì vậy — trừ vị trí Mặt Trăng (do Moon di chuyển rất nhanh, ~13°/ngày) — <strong>celestial condition sẽ giống nhau cho tất cả mọi người sinh cùng một ngày</strong>, bất kể sinh ở đâu hay giờ nào.</p><p>→ Điều này <strong>khác hẳn</strong> với house placement (terrestrial/accidental), vốn phụ thuộc vào <strong>giờ sinh chính xác và địa điểm</strong> (vì houses được tính từ Ascendant, mà Ascendant thay đổi mỗi ~2 giờ và khác nhau theo vĩ độ).</p><p><strong>Ví dụ dễ hình dung:</strong> Sao Kim (Venus) ở Bảo Bình (Aquarius), đi thuận, cách Mặt Trời 20° — đây là &quot;celestial condition&quot; cố định trong ngày hôm đó, ai sinh ngày đó cũng có Venus y hệt vậy. Nhưng Venus đó rơi vào house 5 hay house 10 thì lại tùy thuộc bạn sinh giờ nào, ở đâu — đó là &quot;terrestrial disposition&quot;.</p><h2 id="phan-3-ba-yeu-to-cau-thanh-celestial-condition-theo-thu-tu-uu-tien" tabindex="-1">Phần 3: Ba yếu tố cấu thành Celestial Condition (theo thứ tự ưu tiên) <a class="header-anchor" href="#phan-3-ba-yeu-to-cau-thanh-celestial-condition-theo-thu-tu-uu-tien" aria-label="Permalink to &quot;Phần 3: Ba yếu tố cấu thành Celestial Condition (theo thứ tự ưu tiên)&quot;">​</a></h2><p>Đây là bảng bạn đã xem trước đó (fixed stars → planetary spheres → aspects), nhưng đoạn text bên dưới bảng làm rõ <strong>thứ tự quan trọng (hierarchy)</strong> của 3 yếu tố:</p><h3 id="_1-zodiacal-sign-rulerships-quan-trong-nhat" tabindex="-1">1. Zodiacal sign rulerships (quan trọng nhất) <a class="header-anchor" href="#_1-zodiacal-sign-rulerships-quan-trong-nhat" aria-label="Permalink to &quot;1. Zodiacal sign rulerships (quan trọng nhất)&quot;">​</a></h3><p><strong>Dịch:</strong> Đây là &quot;<strong>thần tính lớn hơn</strong>&quot; (greater divinity) mà các sao cố định (fixed stars) trao truyền cho các cung hoàng đạo. Zodiacal signs, với vai trò là <strong>domiciles</strong> (nhà ở/lãnh địa của hành tinh), cung cấp <strong>&quot;resources and powers&quot;</strong> (nguồn lực và quyền năng) để hành tinh thể hiện bản chất của mình.</p><p>→ Ý tưởng ở đây: hành tinh giống như một &quot;vị vua&quot; — khi ở đúng domicile (lãnh địa) của mình, nó có đầy đủ &quot;tài nguyên&quot; để hành động hiệu quả. Đây chính là nền tảng của khái niệm <strong>essential dignity</strong> (domicile, exaltation, triplicity, bounds, decan — 5 loại dignity cổ điển sẽ học sau).</p><h3 id="_2-orbital-relationship-to-the-sun-quan-trong-thu-nhi" tabindex="-1">2. Orbital relationship to the Sun (quan trọng thứ nhì) <a class="header-anchor" href="#_2-orbital-relationship-to-the-sun-quan-trong-thu-nhi" aria-label="Permalink to &quot;2. Orbital relationship to the Sun (quan trọng thứ nhì)&quot;">​</a></h3><p><strong>Dịch:</strong> Vì Mặt Trời là <strong>&quot;trái tim và trung tâm&quot;</strong> (heart and center) của hệ mặt trời, nên mối quan hệ quỹ đạo của hành tinh với Mặt Trời (<strong>solar phase</strong>) — quyết định tốc độ, hướng đi, và khả năng nhìn thấy (visibility) — đóng vai trò quan trọng thứ hai.</p><p>→ Đây chính là khái niệm <strong>solar phase synodic cycle</strong> trong bảng: hành tinh gần Mặt Trời quá thì bị &quot;combust&quot; (đốt cháy — mất sức mạnh), cách xa vừa đủ thì &quot;free and clear&quot; (tự do, rõ ràng), đi nghịch (retrograde) thì bị coi là suy yếu về mặt biểu hiện.</p><h3 id="_3-aspect-configurations-quan-trong-thu-ba" tabindex="-1">3. Aspect configurations (quan trọng thứ ba) <a class="header-anchor" href="#_3-aspect-configurations-quan-trong-thu-ba" aria-label="Permalink to &quot;3. Aspect configurations (quan trọng thứ ba)&quot;">​</a></h3><p><strong>Dịch:</strong> Đây là các mối quan hệ góc chiếu (aspect) mà hành tinh tạo với các hành tinh khác — được ví như <strong>&quot;hệ thống xã hội của liên minh và hợp tác, hay thù địch và cản trở&quot;</strong> (alliances and cooperation, or enmities and obstacles) mà <strong>&quot;các vị thần hành tinh&quot;</strong> (planetary gods) gặp phải khi cố gắng định hình cuộc đời của thân chủ (native) theo số mệnh của họ.</p><p>→ Ở đây tác giả dùng ngôn ngữ <strong>nhân cách hóa</strong> (personification) rất đặc trưng của truyền thống Hellenistic — hành tinh được coi như những &quot;vị thần&quot; có tính cách, có &quot;bạn bè&quot; (benefic aspect) và &quot;kẻ thù&quot; (malefic aspect) trong lá số, phản ánh triết lý <strong>planetary gods</strong> cai quản định mệnh con người.</p><h2 id="phan-4-an-du-tro-choi-ghe-nhac-musical-chairs" tabindex="-1">Phần 4: Ẩn dụ &quot;trò chơi ghế nhạc&quot; (Musical chairs) <a class="header-anchor" href="#phan-4-an-du-tro-choi-ghe-nhac-musical-chairs" aria-label="Permalink to &quot;Phần 4: Ẩn dụ &quot;trò chơi ghế nhạc&quot; (Musical chairs)&quot;">​</a></h2><p><strong>Dịch:</strong> Sau khi xác định xong celestial condition, bước tiếp theo là xem xét <strong>thời điểm và không gian cụ thể</strong> người đó sinh ra. Tác giả ví: giống như trò chơi <strong>ghế nhạc</strong> (trẻ em nhảy múa quanh vòng ghế, nhạc dừng thì ngồi xuống ghế ngay dưới chân mình) — tại thời khắc sinh ra, các hành tinh &quot;dừng lại&quot; và <strong>rơi vào (drop into)</strong> các house đứng bên dưới quỹ đạo của chúng trên mặt đất.</p><p><strong>Ý nghĩa ẩn dụ:</strong></p><ul><li>&quot;Nhạc&quot; = thời gian trôi qua liên tục, hành tinh luôn di chuyển</li><li>&quot;Nhạc dừng&quot; = khoảnh khắc sinh ra (birth moment) — một lát cắt thời gian cụ thể</li><li>&quot;Ghế&quot; = các house — vị trí cố định trên mặt đất (gắn với horizon/meridian) mà hành tinh &quot;rơi vào&quot; tại khoảnh khắc đó</li></ul><p>→ Đây là cách giải thích trực quan cho khái niệm: celestial condition (hành tinh đang &quot;nhảy múa&quot; ở đâu trên trời) là cố định theo ngày, nhưng <strong>house placement</strong> (hành tinh &quot;ngồi&quot; vào ghế nào) lại phụ thuộc vào chính xác khoảnh khắc và địa điểm sinh — đây là bước chuyển từ <strong>celestial</strong> sang <strong>terrestrial</strong>.</p><p><strong>Câu kết:</strong> &quot;A planet&#39;s own nature, along with its celestial condition, determines how these good and bad human experiences will unfold for the native&quot; — tức là: <strong>bản chất hành tinh + celestial condition</strong> sẽ quyết định các trải nghiệm tốt/xấu đó (do house quy định) sẽ diễn ra <strong>như thế nào</strong>.</p><hr><p><strong>Liên hệ tổng thể (để bạn note vào Project):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CELESTIAL CONDITION (= Essential Dignity, thời Trung Cổ)</span></span>
<span class="line"><span>├─ Giống nhau cho người sinh cùng ngày (trừ Moon)</span></span>
<span class="line"><span>├─ Gồm 3 yếu tố theo thứ tự ưu tiên:</span></span>
<span class="line"><span>│   1. Zodiacal sign rulership (dignity) — quan trọng nhất</span></span>
<span class="line"><span>│   2. Solar phase (quan hệ với Mặt Trời) — quan trọng nhì</span></span>
<span class="line"><span>│   3. Aspect configurations (quan hệ với hành tinh khác) — quan trọng ba</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>TERRESTRIAL DISPOSITION (= Accidental Dignity, thời Trung Cổ)</span></span>
<span class="line"><span>└─ Khác nhau tùy giờ/nơi sinh → House placement</span></span></code></pre></div>`,29)])])}const p=t(a,[["render",s]]);export{d as __pageData,p as default};
